import 'package:cupertino_ui/cupertino_ui.dart' show GlobalCupertinoLocalizations;
import 'package:flutter_localizations/flutter_localizations.dart'
    show GlobalWidgetsLocalizations;
import 'package:material_ui/material_ui.dart';

import '../l10n/app_localizations.dart';

/// Localisation delegates for the app.
///
/// Since Flutter 3.47 the Material and Cupertino localisations live in the
/// `material_ui` and `cupertino_ui` packages; the list generated by
/// `flutter gen-l10n` (`AppLocalizations.localizationsDelegates`) still points
/// to the deprecated copies in `flutter_localizations`, which `material_ui`
/// widgets do not see. Use this list instead.
const appLocalizationsDelegates = <LocalizationsDelegate<dynamic>>[
  AppLocalizations.delegate,
  GlobalMaterialLocalizations.delegate,
  GlobalCupertinoLocalizations.delegate,
  GlobalWidgetsLocalizations.delegate,
];

const appSupportedLocales = AppLocalizations.supportedLocales;
